package com.trombokendu.chronos.scenario;import com.trombokendu.chronos.analytics.*;import java.time.*;import java.util.random.*;public record CapCategory(String category,double perDay) implements Policy{public SpendModel wrap(SpendModel b){return new SpendModel(){public double sampleDaily(RandomGenerator r,LocalDate d){return category.equalsIgnoreCase(d.getDayOfWeek().name())?Math.min(perDay,b.sampleDaily(r,d)):Math.min(perDay,b.sampleDaily(r,d));}};}}
